function addBox(parent, m, w, h, d, x, y, z, name) {
  const mesh5 = new Mesh(new BoxGeometry(w, h, d), m);
  mesh5.position.set(x, y, z);
  mesh5.castShadow = true;
  mesh5.receiveShadow = true;
  mesh5.name = name;
  parent.add(mesh5);
  return mesh5;
}
function addCyl(parent, m, rTop, rBottom, h, seg2, x, y, z, name) {
  const mesh5 = new Mesh(new CylinderGeometry(rTop, rBottom, h, seg2), m);
  mesh5.position.set(x, y, z);
  mesh5.castShadow = true;
  mesh5.receiveShadow = true;
  mesh5.name = name;
  parent.add(mesh5);
  return mesh5;
}
function shellDimsOf(definition) {
  const meta = definition.metadata;
  const num = (key, fallback) => {
    const v = Number(meta[key]);
    return Number.isFinite(v) && v > 0 ? v : fallback;
  };
  return {
    width: num("width", SALOON_LAYOUT.width),
    depth: num("depth", SALOON_LAYOUT.depth),
    height: num("height", SALOON_LAYOUT.height),
    doorWidth: num("doorWidth", SALOON_LAYOUT.doorWidth)
  };
}
