  for (let r = 0; r < 3; r++) {
    for (let c = 0; c < 3; c++) {
      const bx = -0.14 + c * 0.14;
      const by = seatH + 0.14 + r * 0.16;
      const button = mesh2(new SphereGeometry(0.012, 6, 6), MAT.brassDark(), bx, by, -0.16 - r * 0.01);
      g.add(button);
    }
  }
  const column = mesh2(new CylinderGeometry(0.03, 0.04, seatH - 0.15, 10), MAT.brass(), 0, (seatH - 0.15) / 2 + 0.1, 0);
  g.add(column);
