  divHeader: sheriffUuid("0d"),
  divSouth: sheriffUuid("0e"),
  cellDivider: sheriffUuid("0f"),
  barANorth: sheriffUuid("10"),
  barASouth: sheriffUuid("11"),
  barAHeader: sheriffUuid("12"),
