  addBox4(g, M_.trim, lw, lining * 2, liningDepth, 0, hh, 0, "window-liner-top");
  addBox4(g, M_.trim, lining * 2, height - lining * 2, liningDepth, -hw, 0, 0, "window-liner-left");
