  addBox4(g, M_.trim, lw + casing * 2, casing, 0.025, 0, -hh - lining - casing / 2, casingZ, "window-casing-bottom");
  addBox4(g, M_.trim, casing, height + lining * 2, 0.025, -hw - lining - casing / 2, 0, casingZ, "window-casing-left");
  addBox4(g, M_.trim, casing, height + lining * 2, 0.025, hw + lining + casing / 2, 0, casingZ, "window-casing-right");
  addBox4(g, M_.trim, lw + casing * 2 + 0.08, 0.07, 0.18, 0, -hh - lining - 0.09, face + 0.08, "window-sill");
  addBox4(g, M_.trim, lw + casing * 2 + 0.08, 0.1, 0.1, 0, hh + lining + 0.05, face + 0.03, "window-lintel");
