function buildGable(M_, holes) {
  const shape = new Shape();
  shape.moveTo(-STABLE_LAYOUT.width / 2, 0);
  shape.lineTo(STABLE_LAYOUT.width / 2, 0);
  shape.lineTo(0, STABLE_LAYOUT.roof.ridgeY - STABLE_LAYOUT.wallHeight + 0.01);
  shape.closePath();
  for (const h of holes) {
    const path = new Path();
    path.moveTo(h.x - h.w / 2, h.y);
    path.lineTo(h.x - h.w / 2, h.y + h.h);
    path.lineTo(h.x + h.w / 2, h.y + h.h);
    path.lineTo(h.x + h.w / 2, h.y);
    path.closePath();
    shape.holes.push(path);
  }
  const geo2 = new ExtrudeGeometry(shape, { depth: STABLE_LAYOUT.wallThickness, bevelEnabled: false });
  const mesh5 = new Mesh(geo2, M_.siding);
  mesh5.castShadow = true;
  mesh5.receiveShadow = true;
  mesh5.name = "gable-infill";
  return mesh5;
}
