  addBox5(g, M3.woodTrim, win.width, 0.05, 0.03, 0, glassY, barZ, "gunshop-window-cross-h");
  addBox5(g, M3.woodDark, win.width + 0.24, 0.06, 0.14, 0, win.sillY - 0.15, wallFaceZ + 0.06, "gunshop-window-sill");
