    for (const sx of [-1, 1]) {
      addBox6(g, M2.woodGray, T, bodyH, DEP - 2 * T - 0.02, sx * (0.5 - T / 2), baseY + bodyH / 2, 0, `town-trough-end-${sx < 0 ? "w" : "e"}`);
    }
    addBox6(g, M2.woodDark, 1 - 2 * T - 0.05, 0.02, DEP - 2 * T - 0.05, 0, baseY + 0.01, 0, "town-trough-floor");
