  box3(g, MAT3.iron(), 0.5, 0.02, 0.015, 1.45, 1.665, -depth / 2 + 0.05);
  const stain1 = mesh4(new PlaneGeometry(0.24, 0.11), MAT3.blood(), -0.62, 1.0015, depth / 2 - 0.18);
  stain1.rotation.x = -Math.PI / 2;
  stain1.name = "blood-stain-counter";
