function findSafeSpawnPosition(collisionWorld2, options) {
  const radius = options.radius ?? 0.35;
  const height = options.height ?? 1.7;
  const nudges = options.nudges ?? DEFAULT_NUDGES;
  const bounds = collisionWorld2.getCollisionBounds();
  const intersectsWorld = (probe) => {
    const feetY = probe.y - height;
    for (const b of bounds) {
      const overlapX = probe.x + radius > b.min.x && probe.x - radius < b.max.x;
      const overlapZ = probe.z + radius > b.min.z && probe.z - radius < b.max.z;
      const overlapY = feetY < b.max.y && probe.y > b.min.y;
      if (overlapX && overlapZ && overlapY)
        return true;
    }
    return false;
  };
  let fallback = options.candidates[0] ?? { x: 0, y: height, z: 0 };
  for (const candidate of options.candidates) {
    for (const nudge of nudges) {
      const probe = { x: candidate.x + nudge.x, y: candidate.y + 0.05, z: candidate.z + nudge.z };
      if (intersectsWorld(probe))
        continue;
      const settled = collisionWorld2.movePlayer(probe, { x: 0, y: -0.2, z: 0 }, radius, height);
      if (!settled.grounded)
        continue;
      const stable = collisionWorld2.movePlayer(settled.position, { x: 0, y: 0, z: 0 }, radius, height);
      if (stable.blockedX || stable.blockedY || stable.blockedZ)
        continue;
      return settled.position;
    }
  }
  return fallback;
}

