// src/editor/MoveClamp.ts
var DEFAULT_LATERAL_OVERLAP_THRESHOLD = 1e-3;
function clampAxisDelta(input2) {
  const { axis, delta } = input2;
  const threshold = input2.lateralThreshold ?? DEFAULT_LATERAL_OVERLAP_THRESHOLD;
  if (delta === 0)
    return 0;
  const [j1, j2] = axis === "x" ? ["y", "z"] : axis === "y" ? ["x", "z"] : ["x", "y"];
  let limitPlus = Infinity;
  let limitMinus = -Infinity;
  for (const blocker of input2.blockers) {
    const lat1 = Math.min(input2.selected.max[j1], blocker.max[j1]) - Math.max(input2.selected.min[j1], blocker.min[j1]);
    const lat2 = Math.min(input2.selected.max[j2], blocker.max[j2]) - Math.max(input2.selected.min[j2], blocker.min[j2]);
    if (lat1 < threshold || lat2 < threshold)
      continue;
    const sMin = input2.selected.min[axis];
    const sMax = input2.selected.max[axis];
    const bMin = blocker.min[axis];
    const bMax = blocker.max[axis];
    if (sMax <= bMin || sMin >= bMax) {
      if (sMax <= bMin)
        limitPlus = Math.min(limitPlus, bMin - sMax);
      else
        limitMinus = Math.max(limitMinus, bMax - sMin);
    } else if (bMin <= sMin && sMax <= bMax || sMin <= bMin && bMax <= sMax) {
      continue;
    } else if (sMin <= bMin) {
      limitPlus = Math.min(limitPlus, 0);
    } else {
      limitMinus = Math.max(limitMinus, 0);
    }
  }
  if (delta > 0)
    return Math.max(0, Math.min(delta, limitPlus));
  return Math.min(0, Math.max(delta, limitMinus));
}
function collectBlockerBoxes(scene2, manager2, excludeUuid, out = []) {
  out.length = 0;
  for (const definition of manager2.getAllObjects()) {
    if (definition.uuid === excludeUuid)
      continue;
    const mesh5 = scene2.getObjectByProperty("uuid", definition.uuid);
    if (!mesh5 || isDebugHelper(mesh5))
      continue;
    out.push(new Box3().setFromObject(mesh5));
  }
  return out;
}
function makeSceneAxisClamp(scene2, manager2, lateralThreshold) {
  const selectedBox = new Box3();
  return (uuid, axis, delta) => {
    if (delta === 0)
      return 0;
    const mesh5 = scene2.getObjectByProperty("uuid", uuid);
    if (!mesh5 || isDebugHelper(mesh5))
      return delta;
    const definition = manager2.getObject(uuid);
    if (!definition || definition.metadata.editable === false)
      return delta;
    selectedBox.setFromObject(mesh5);
    const blockers = collectBlockerBoxes(scene2, manager2, uuid);
    return clampAxisDelta({ selected: selectedBox, axis, delta, blockers, lateralThreshold });
  };
}

// src/editor/SelectionInfo.ts
var NO_SELECTION_INFO = Object.freeze({
  name: "None",
  uuid: "No selection",
  position: "\u2014",
  rotation: "\u2014",
  scale: "\u2014"
});
