// src/horse/HorseVitals.ts
var HorseStamina = class {
  maxStamina;
  currentStamina;
  sinceDrainSeconds = 0;
  fatigued = false;
  constructor(max = HORSE_STAMINA.max) {
    this.maxStamina = Math.max(1, max);
    this.currentStamina = this.maxStamina;
  }
  get max() {
    return this.maxStamina;
  }
  get current() {
    return this.currentStamina;
  }
  get ratio() {
    return this.currentStamina / this.maxStamina;
  }
  /** Fatigue lock engaged — gallop denied until recovery (spec §5). */
  get isFatigued() {
    return this.fatigued;
  }
  /** Whether the gallop gait is currently available. */
  canGallop() {
    return !this.fatigued && this.currentStamina > 0;
  }
  /**
   * Advance the pool for one frame with the gait the horse is ACTUALLY
   * holding (its current speed band, not the requested target).
   */
  update(deltaSeconds, activeGait) {
    const dt = Math.max(0, deltaSeconds);
    let rate = 0;
    switch (activeGait) {
      case "gallop":
        rate = -HORSE_STAMINA.gallopDrain;
        break;
      case "canter":
        rate = -HORSE_STAMINA.canterDrain;
        break;
      case "walk":
        rate = HORSE_STAMINA.walkRegen;
        break;
      case "idle":
        rate = HORSE_STAMINA.idleRegen;
        break;
      case "trot":
        rate = HORSE_STAMINA.trotRegen;
        break;
    }
    if (rate < 0) {
      this.sinceDrainSeconds = 0;
      this.currentStamina = Math.max(0, this.currentStamina + rate * dt);
      if (!this.fatigued && this.currentStamina <= HORSE_STAMINA.fatigueLock)
        this.fatigued = true;
      return;
    }
    this.sinceDrainSeconds += dt;
    if (rate > 0 && this.sinceDrainSeconds >= HORSE_STAMINA.regenDelay) {
      this.currentStamina = Math.min(this.maxStamina, this.currentStamina + rate * dt);
    }
    if (this.fatigued && this.currentStamina >= HORSE_STAMINA.fatigueRecover)
      this.fatigued = false;
  }
  /** Immediate one-shot cost (hard collision panic, spook surge...). */
  spend(amount) {
    if (amount <= 0 || this.currentStamina <= 0)
      return 0;
    const applied = Math.min(this.currentStamina, amount);
    this.currentStamina -= applied;
    this.sinceDrainSeconds = 0;
    if (!this.fatigued && this.currentStamina <= HORSE_STAMINA.fatigueLock)
      this.fatigued = true;
    return applied;
  }
  /** Full restore (revive / restore-from-save). Values inside the hysteresis
   * band keep the current fatigue lock; crossing a threshold updates it. */
  reset(value = this.maxStamina) {
    this.currentStamina = Math.min(this.maxStamina, Math.max(0, value));
    this.sinceDrainSeconds = 0;
    if (this.currentStamina <= HORSE_STAMINA.fatigueLock)
      this.fatigued = true;
    else if (this.currentStamina >= HORSE_STAMINA.fatigueRecover)
      this.fatigued = false;
  }
};

