var HORSE_SAVE_KEY = "ai-western-game.playable-map.horse.v1";
var MAX_COORD = WORLD_PLAYABLE_HALF;
function browserStorage2() {
  try {
    const storage2 = globalThis.localStorage;
    return storage2 ?? null;
  } catch {
    return null;
  }
}
