    handled = editor.moveSelected("left", fast);
  if (event.code === "ArrowRight")
    handled = editor.moveSelected("right", fast);
  if (event.code === "ArrowUp")
    handled = editor.moveSelected("forward", fast);
  if (event.code === "ArrowDown")
    handled = editor.moveSelected("backward", fast);
  if (event.code === "PageUp")
    handled = editor.moveSelected("up", fast);
  if (event.code === "PageDown")
    handled = editor.moveSelected("down", fast);
  if (event.code === "KeyQ")
    handled = editor.rotateSelected("y", 1, fast);
  if (event.code === "KeyE")
    handled = editor.rotateSelected("y", -1, fast);
  if (event.code === "KeyR")
    handled = editor.rotateSelected("x", 1, fast);
  if (event.code === "KeyF")
    handled = editor.rotateSelected("x", -1, fast);
  if (event.code === "KeyT")
    handled = editor.rotateSelected("z", 1, fast);
  if (event.code === "KeyG")
    handled = editor.rotateSelected("z", -1, fast);
